}

// Function to check if the head has collided with itself
int hasHeadCollision(int x, int y) {
    return (head == x && head == y);
}

// Main game loop
while (true) {
    // Poll for key presses
    int key = (key == KEYS_UP || key == KEYS_DOWN)? 1 : 0;

    // Move the head
    int dx = key? 1 : -1; // Move in the opposite direction of the key pressed
    int dy = key? 0 : -1; // Move down

    // Check collision
    if (hasCollidedWithWall(head + dx, head + dy)) {
        // Collision with wall, reset snake and head position
        head = 0;
        tail = snakeLength - 1;
        printf("Snake hits wall!\n");
        break;
    }

    // Check if the snake has collided with itself
    if (hasHeadCollision(head + dx, head + dy)) {
        // Collision with own head, reset snake and head position
        head = 0;
        printf("Snake hits own head!\n");
        break;
    }

    // Update the position of the head
    head = (head + dx) % snakeLength;

    // Draw the snake
    drawSnake(head, 0);

    // Check for termination condition
    if (key == KEYS_QUIT) {
        break;
    }

    // Sleep to prevent console output jitter
