```java
public class PowerOfThreeChecker {
    private final static int THREE_power = 3;

    public boolean isPowerOfThree(int n) {
        return (n & (n >>> 23)) == THREE_power;
    }

    public static void main(String[] args) {
        System.out.println(isPowerOfThree(27));  // Should print true
        System.out.println(isPowerOfThree(0));  // Should print false
        System.out.println(isPowerOfThree(-1));  // Should print false
        System.out.println(TWO_power_of_three);  // Should print true
    }
}

