#include <iostream>
#include <fstream>
#include <sstream>

// Function to count occurrences of a word in a file
int countOccurrences(std::string word, const std::string& filename) {
    std::ifstream file(filename);

    if (!file.is_open()) {
        std::cerr << "Could not open file!" << std::endl;
        return 1; // Return 1 to indicate an error
    }

    std::string line;
    std::getline(file, line);

    int count = 0;

    for (const auto& char : line) {
        if (char == word) {
            count++;  // Increment count for each occurrence of the word
        }
    }

    return count;
}

